            put("tableName", "TEST_QUERY_DB_TABLE");
            put("maxValueCol", "id");
        }});
        runner.enqueue("".getBytes(), new HashMap<String, String>() {{
            put("tableName", "TEST_QUERY_DB_TABLE_2");
            put("maxValueCol", "id");
